
CREATE OR REPLACE VIEW analytics.vw_kpi_overview AS SELECT COUNT(DISTINCT order_id) AS total_orders, COUNT(DISTINCT order_item_id) AS total_order_items, COALESCE(SUM(quantity), 0) AS total_units_sold, ROUND(COALESCE(SUM(sales), 0), 2) AS total_recorded_sales, ROUND(COALESCE(SUM(discount), 0), 2) AS total_discounts, ROUND(COALESCE(SUM(order_item_total), 0), 2) AS total_net_item_value, ROUND(COALESCE(SUM(order_item_total), 0) / NULLIF(COUNT(DISTINCT order_id), 0), 2) AS average_order_value, ROUND(100.0 * COALESCE(SUM(discount), 0) / NULLIF(SUM(sales), 0), 2) AS discount_rate_pct FROM analytics.fact_order_items;
